function ar_date(string $value,string $label):string{$d=DateTimeImmutable::createFromFormat('!Y-m-d',$value);$e=DateTimeImmutable::getLastErrors();if(!$d||($e!==false&&(($e['warning_count']??0)>0||($e['error_count']??0)>0))||$d->format('Y-m-d')!==$value)ar_out(['ok'=>false,'error'=>$label.' is invalid.'],422);return$value;}
function ar_read(string $path):array{$raw=is_file($path)?file_get_contents($path):false;$value=$raw?json_decode($raw,true):null;return is_array($value)?$value:[];}
try{$user=tt_require_login();if(!tt_user_can_open_module($user,'Accounts'))ar_out(['ok'=>false,'error'=>'Accounts permission required.'],403);$entity=strtoupper(trim((string)($_GET['entity']??'')));if(!in_array($entity,['TTI','BRM','TG'],true)||!tt_user_can_access_entity($user,$entity,'View'))ar_out(['ok'=>false,'error'=>'You do not have permission for this legal entity.'],403);$today=(new DateTimeImmutable('now',new DateTimeZone('Asia/Karachi')))->format('Y-m-d');$asOf=ar_date((string)($_GET['asOf']??$today),'As-of date');$from=ar_date((string)($_GET['from']??substr($asOf,0,4).'-01-01'),'From date');if($from>$asOf)ar_out(['ok'=>false,'error'=>'From date cannot be after the as-of date.'],422);$store=ar_read(AR_FILE);$master=ar_read(AR_MASTER);$catalog=[];foreach(array_merge((array)($master['chart']??[]),(array)($master['peopleSubledgers']??[]))as$account)if(is_array($account)&&isset($account['code']))$catalog[(string)$account['code']]=$account;$journals=array_values(array_filter((array)($store['journals']??[]),fn($j)=>is_array($j)&&($j['entity']??'')===$entity&&($j['status']??'')==='Posted'&&($j['date']??'')<=$asOf));usort($journals,fn($a,$b)=>strcmp((string)$a['date'],(string)$b['date'])?:strcmp((string)$a['id'],(string)$b['id']));$balances=[];$ledger=[];foreach($journals as$j)foreach((array)($j['lines']??[])as$line){if(!is_array($line))continue;$code=(string)($line['account']??'');$dr=round((float)($line['debit']??0),2);$cr=round((float)($line['credit']??0),2);$balances[$code]=($balances[$code]??0)+$dr-$cr;$ledger[]=['date'=>(string)$j['date'],'journalId'=>(string)$j['id'],'sourceType'=>(string)($j['sourceType']??''),'reference'=>(string)($j['reference']??''),'narration'=>(string)($j['narration']??''),'account'=>$code,'accountName'=>(string)($line['accountName']??$catalog[$code]['name']??$code),'debit'=>$dr,'credit'=>$cr];}$trial=[];foreach($balances as$code=>$net){if(abs($net)<.005)continue;$a=$catalog[$code]??[];$trial[]=['account'=>$code,'name'=>(string)($a['name']??$code),'class'=>(string)($a['class']??'Other'),'debit'=>$net>0?round($net,2):0,'credit'=>$net<0?round(abs($net),2):0];}usort($trial,fn($a,$b)=>strcmp($a['account'],$b['account']));$period=array_values(array_filter($journals,fn($j)=>($j['date']??'')>=$from));$periodBalances=[];foreach($period as$j)foreach((array)($j['lines']??[])as$line){$code=(string)($line['account']??'');$periodBalances[$code]=($periodBalances[$code]??0)+(float)($line['debit']??0)-(float)($line['credit']??0);}$income=[];$expenses=[];$profit=0.0;foreach($periodBalances as$code=>$net){$a=$catalog[$code]??[];$class=(string)($a['class']??'Other');if($class==='Revenue'){$amount=round(-$net,2);$income[]=['account'=>$code,'name'=>(string)($a['name']??$code),'amount'=>$amount];$profit+=$amount;}elseif($class==='Expense'||$code==='7100'){$amount=round($net,2);$expenses[]=['account'=>$code,'name'=>(string)($a['name']??$code),'amount'=>$amount];$profit-=$amount;}}$assets=[];$liabilities=[];$equity=[];$cumulativeProfit=0.0;foreach($balances as$code=>$net){$a=$catalog[$code]??[];$class=(string)($a['class']??'Other');$name=(string)($a['name']??$code);if($class==='Asset'&&abs($net)>.005)$assets[]=['account'=>$code,'name'=>$name,'amount'=>round($net,2)];elseif($class==='Liability'&&abs($net)>.005)$liabilities[]=['account'=>$code,'name'=>$name,'amount'=>round(-$net,2)];elseif($class==='Equity'&&abs($net)>.005)$equity[]=['account'=>$code,'name'=>$name,'amount'=>round(-$net,2)];elseif($class==='Revenue')$cumulativeProfit+=-$net;elseif($class==='Expense'||$code==='7100')$cumulativeProfit-=$net;}if(abs($cumulativeProfit)>.005)$equity[]=['account'=>'CURRENT-EARNINGS','name'=>'Current cumulative earnings','amount'=>round($cumulativeProfit,2)];$totalDr=round(array_sum(array_column($trial,'debit')),2);$totalCr=round(array_sum(array_column($trial,'credit')),2);ar_out(['ok'=>true,'entity'=>$entity,'from'=>$from,'asOf'=>$asOf,'generalLedger'=>$ledger,'trialBalance'=>['rows'=>$trial,'totalDebit'=>$totalDr,'totalCredit'=>$totalCr,'balanced'=>abs($totalDr-$totalCr)<.005],'profitAndLoss'=>['income'=>$income,'expenses'=>$expenses,'profit'=>round($profit,2)],'balanceSheet'=>['assets'=>$assets,'liabilities'=>$liabilities,'equity'=>$equity,'totalAssets'=>round(array_sum(array_column($assets,'amount')),2),'totalLiabilitiesAndEquity'=>round(array_sum(array_column($liabilities,'amount'))+array_sum(array_column($equity,'amount')),2)],'serverNow'=>gmdate('c')]);}catch(Throwable $e){ar_out(['ok'=>false,'error'=>'Accounts reports could not be prepared.'],500);}
